"use client";

import { useRouter } from "@bprogress/next/app";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "@purplefish-ai/shadcn-ui/components/ui/card";
import { Skeleton } from "@purplefish-ai/shadcn-ui/components/ui/skeleton";
import { useQuery } from "@tanstack/react-query";
import { useSearchParams } from "next/navigation";
import { useEffect, useState } from "react";

import { useTRPC } from "@/trpc/client";

import type { Engagement } from "./components/engagement-selector";
import { EngagementSelector } from "./components/engagement-selector";
import { LogFilters } from "./components/log-filters";
import { LogViewer } from "./components/log-viewer";
import { MetricCards } from "./components/metric-cards";
import { SequenceItemsCard } from "./components/sequence-items-card";
import { TimelineChart } from "./components/timeline-chart";
import type { TransformedLog } from "./lib/metrics";
import { calculateMetricsSummary } from "./lib/metrics";

interface DebugPageProps {
  opportunity: {
    id: string;
    candidate: {
      id: string;
      firstName: string;
      lastName: string;
      phoneNumber: string | null;
    };
    engagements: Engagement[];
    sequenceItems: {
      id: string;
      createdAt: Date;
      updatedAt: Date;
      channel: string;
      scheduledAt: Date | null;
      triggeredAt: Date | null;
      cancelledAt: Date | null;
      cancelledReason: string | null;
      templateId: string | null;
      inngestRunIds: string[];
      template: {
        id: string;
        name: string;
        channel: string;
        subjectTemplate: string | null;
      } | null;
      engagement: {
        id: string;
        status: string;
        createdAt: Date;
      } | null;
      smsMessage: {
        id: string;
        message: string;
        createdAt: Date;
      } | null;
      email: {
        id: string;
        subject: string | null;
        createdAt: Date;
      } | null;
      triggeredByUser: {
        id: string;
        firstName: string | null;
        lastName: string | null;
      } | null;
    }[];
  };
  jobId: string;
}

export function DebugPage({ opportunity }: DebugPageProps) {
  const router = useRouter();
  const searchParams = useSearchParams();
  const [selectedEngagementId, setSelectedEngagementId] = useState<string>("");
  const [searchQuery, setSearchQuery] = useState<string>("");
  const [selectedLevel, setSelectedLevel] = useState<string>("all");
  const trpc = useTRPC();

  const selectedEngagement = opportunity.engagements.find(
    (e) => e.id === selectedEngagementId,
  );

  const { data: logsData, isLoading } = useQuery(
    trpc.debug.fetchDatadogLogs.queryOptions(
      {
        livekitJobId: selectedEngagement?.livekitJobId ?? "",
        startTime: selectedEngagement?.createdAt.toISOString() ?? "",
        endTime:
          selectedEngagement?.completedAt?.toISOString() ??
          new Date().toISOString(),
      },
      {
        enabled: Boolean(selectedEngagement?.livekitJobId),
      },
    ),
  );

  const logs = logsData?.logs as TransformedLog[] | undefined;

  // Initialize from URL param on mount
  useEffect(() => {
    const engagementId = searchParams.get("engagement");
    if (
      engagementId &&
      opportunity.engagements.some((e) => e.id === engagementId)
    ) {
      void handleEngagementChange(engagementId);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [searchParams, handleEngagementChange, opportunity.engagements.some]);

  const handleEngagementChange = async (engagementId: string) => {
    setSelectedEngagementId(engagementId);

    // Update URL
    const params = new URLSearchParams(searchParams.toString());
    params.set("engagement", engagementId);
    void router.push(`?${params.toString()}`);
  };

  const metricsSummary = calculateMetricsSummary(logs ?? []);

  return (
    <div className="container mx-auto space-y-6 p-6">
      {/* Sequence Items Card - Always visible at opportunity level */}
      <SequenceItemsCard sequenceItems={opportunity.sequenceItems} />

      <Card>
        <CardHeader>
          <CardTitle>Engagement Debug Tools</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <EngagementSelector
            engagements={opportunity.engagements}
            selectedEngagementId={selectedEngagementId}
            onEngagementChange={handleEngagementChange}
          />

          {selectedEngagement && (
            <div className="grid grid-cols-2 gap-4 text-sm md:grid-cols-3">
              <div>
                <span className="font-medium">Status:</span>{" "}
                {selectedEngagement.status}
              </div>
              <div>
                <span className="font-medium">Model:</span>{" "}
                {selectedEngagement.agentModel || "N/A"}
              </div>
              <div>
                <span className="font-medium">LiveKit Job ID:</span>{" "}
                {selectedEngagement.livekitJobId || "N/A"}
              </div>
              <div>
                <span className="font-medium">Room Name:</span>{" "}
                {selectedEngagement.roomName || "N/A"}
              </div>
              <div>
                <span className="font-medium">Duration:</span>{" "}
                {selectedEngagement.durationSeconds != null
                  ? `${selectedEngagement.durationSeconds}s`
                  : "N/A"}
              </div>
              <div>
                <span className="font-medium">Completed At:</span>{" "}
                {selectedEngagement.completedAt
                  ? new Date(selectedEngagement.completedAt).toLocaleString()
                  : "N/A"}
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      {isLoading && (
        <div className="space-y-4">
          <Skeleton className="h-24 w-full" />
          <Skeleton className="h-24 w-full" />
          <Skeleton className="h-24 w-full" />
        </div>
      )}

      {logs && logs.length > 0 && selectedEngagementId !== "" && (
        <>
          {/* Metrics Summary Cards */}
          <MetricCards metricsSummary={metricsSummary} />

          {/* Timeline Chart */}
          {metricsSummary.timeline.length > 0 && (
            <Card>
              <CardHeader>
                <CardTitle className="text-sm font-medium">
                  Performance Timeline
                </CardTitle>
              </CardHeader>
              <CardContent>
                <TimelineChart timeline={metricsSummary.timeline} />
              </CardContent>
            </Card>
          )}
        </>
      )}

      {selectedEngagementId !== "" && (
        <Card>
          <CardHeader>
            <CardTitle>Datadog Logs</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            {/* Filters */}
            <LogFilters
              searchQuery={searchQuery}
              onSearchChange={setSearchQuery}
              selectedLevel={selectedLevel}
              onLevelChange={setSelectedLevel}
            />

            {/* Logs */}
            {isLoading ? (
              <div className="space-y-2">
                <Skeleton className="h-16 w-full" />
                <Skeleton className="h-16 w-full" />
                <Skeleton className="h-16 w-full" />
              </div>
            ) : selectedEngagement?.livekitJobId ? (
              logs && logs.length === 0 ? (
                <p className="text-sm text-gray-500 dark:text-gray-400">
                  No logs found for this engagement.
                </p>
              ) : (
                <LogViewer
                  logs={logs ?? []}
                  searchQuery={searchQuery}
                  selectedLevel={selectedLevel}
                />
              )
            ) : (
              <p className="text-sm text-gray-500 dark:text-gray-400">
                This engagement does not have a LiveKit job ID.
              </p>
            )}
          </CardContent>
        </Card>
      )}
    </div>
  );
}

