const SortIcon = ({ column }: { column: Column<JobTableRow> }) => {
  if (column.getIsSorted() === false) {
    return <IconSwapVert className="ml-2 h-4 w-4" />;
  }
  if (column.getIsSorted() === "asc") {
    return <IconKeyboardArrowUp className="ml-2 h-4 w-4" />;
  }
  return <IconKeyboardArrowDown className="ml-2 h-4 w-4" />;
};

export default function JobTable({
  jobs,
  pagination,
  sorting,
  columnFilters,
  query,
  totalCount,
}: {
  jobs: JobTableRow[];
  pagination: PaginationState;
  sorting: SortingState;
  columnFilters: ColumnFiltersState;
  query?: string;
  totalCount: number;
}) {
  const { organizationId } = useOrganizationContext();
  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();

  const [columnVisibility, setColumnVisibility] = useState<VisibilityState>({
    createdAt: false,
    companyName: false,
    jobLocation: false,
    deployedAt: false,
    advanced: false,
    notContacted: false,
  });

  const createQueryString = useCallback(
    (newParams: { name: string; value: string }[]) => {
      return addParamToSearchQueryString(searchParams, newParams);
    },
    [searchParams],
  );

  const onQueryChange = (newValue: string) => {
    router.replace(
      pathname +
        "?" +
        createQueryString([
          {
            name: "query",
            value: newValue,
          },
          {
            name: "page",
            value: "1",
          },
        ]),
    );
  };
  const debouncedOnQueryChange = debounce(onQueryChange, 300);

  const getDateLabel = (row: Row<JobTableRow>) => {
    const prefix = row.original.lastActivatedAt ? "activated" : "added";
    return `${prefix} ${generateRelativeDateString(
      row.original.lastActivatedAt ?? row.original.createdAt,
    )}`;
  };

  const columns = useMemo(() => {
    const cols: ColumnDef<JobTableRow>[] = [
      {
        accessorKey: "title",
        accessorFn: (row) => `${row.title}`,
        meta: "Title",
        header: "Title",
        enableHiding: false,
        cell: ({ row }) => {
          const secondaryDataPoints = [];
          if (columnVisibility.companyName === false) {
            secondaryDataPoints.push(row.original.companyName);
          }
          if (
            columnVisibility.jobLocation === false &&
            row.original.jobLocation
          ) {
            secondaryDataPoints.push(row.original.jobLocation);
          }

          return (
            <>
              <p className="text-base font-semibold">{row.original.title}</p>
              {secondaryDataPoints.length > 0 && (
                <p className="text-muted-foreground">
                  {secondaryDataPoints.join(" • ")}
                </p>
              )}
              {columnVisibility.createdAt === false && (
                <div className="flex items-center gap-x-2">
                  <p className="text-muted-foreground mt-1 text-xs italic">
                    {getDateLabel(row)}
                    {(row.original.source !== JobSource.MANUAL ||
                      row.original.atsId) && (
                      <span className="text-muted-foreground text-xs italic">
                        &nbsp;• ATS ID: {row.original.atsId || "Missing"}
                      </span>
                    )}
                    {row.original.clientId && (
                      <span className="text-muted-foreground text-xs italic">
                        &nbsp;• Client ID: {row.original.clientId}
                      </span>
                    )}
                  </p>
                </div>
              )}
            </>
          );
        },
      },
      {
        accessorKey: "companyName",
        meta: "Company",
        header: "Company",
        cell: ({ row }) => {
          return (
            <div className="text-muted-foreground text-center">
              {row.original.companyName}
            </div>
          );
        },
      },
      {
        accessorKey: "jobLocation",
        meta: "Location",
        header: "Location",
        cell: ({ row }) => {
          return (
            <div className="text-muted-foreground text-center">
              {row.original.jobLocation}
            </div>
          );
        },
      },
      {
        accessorKey: "createdAt",
        header: ({ column }) => {
          return (
            <Button
              variant="link"
              className="px-0"
              onClick={() =>
                column.toggleSorting(column.getIsSorted() === "asc")
              }
            >
              Added At
              <SortIcon column={column} />
            </Button>
          );
        },
        meta: "Added At",
        accessorFn: (row) => {
          return row;
        },
        cell: ({ row }) => {
          return (
            <div className="text-muted-foreground text-center">
              {format(row.original.createdAt, "M/d, h:mm a")}
            </div>
          );
        },
      },
      {
        accessorKey: "deployedAt",
        header: ({ column }) => {
          return (
            <Button
              variant="link"
              className="px-0"
              onClick={() =>
                column.toggleSorting(column.getIsSorted() === "asc")
              }
            >
              Activated At
              <SortIcon column={column} />
            </Button>
          );
        },
        meta: "Activated At",
        accessorFn: (row) => {
          return row;
        },
        cell: ({ row }) => {
          const date = row.original.lastActivatedAt
            ? row.original.lastActivatedAt
            : row.original.deployedAt;
          return (
            <div className="text-muted-foreground text-center">
              {date ? format(date, "M/d/yy, h:mm a") : ""}
            </div>
          );
        },
      },
      {
        accessorKey: "candidates",
        header: () => {
          return <div className="text-center">Candidates</div>;
        },
        meta: "Candidates",
        accessorFn: (row) => {
          return row;
        },
        cell: ({ row }) => {
          return (
            <div className="text-muted-foreground text-center">
              {row.original.totalOpportunities}
            </div>
          );
        },
      },
      {
        accessorKey: "conversations",
        header: () => {
          return <div className="text-center">Conversations</div>;
        },
        meta: "Conversations",
        accessorFn: (row) => {
          return row;
        },
        cell: ({ row }) => {
          return (
            <div className="text-muted-foreground text-center" role="button">
              {row.original.totalConversations}
            </div>
          );
        },
      },
      {
        accessorKey: "completed",
        header: () => {
          return <div className="text-center">Completed</div>;
        },
        meta: "Completed",
        accessorFn: (row) => {
          return row;
        },
        cell: ({ row }) => {
          return (
            <div className="text-muted-foreground text-center" role="button">
              {row.original.totalSucceeded}
            </div>
          );
        },
      },
      {
        accessorKey: "advanced",
        header: () => {
          return <div className="text-center">Advanced</div>;
        },
        meta: "Advanced",
        accessorFn: (row) => {
          return row;
        },
        cell: ({ row }) => {
          return (
            <div className="text-muted-foreground text-center">
              {row.original.totalAdvanced}
            </div>
          );
        },
      },
    ];
    cols.push({
      accessorKey: "inProgress",
      header: () => {
        return <div className="text-center">In Progress</div>;
      },
      meta: "In Progress",

      accessorFn: (row) => {
        return row;
      },
      cell: ({ row }) => {
        return (
          <div className="text-muted-foreground text-center">
            {row.original.inProgress}
          </div>
        );
      },
    });

    cols.push({
      accessorKey: "notContacted",
      header: () => {
        return <div className="text-center">Not Contacted</div>;
      },
      meta: "Not Contacted",
      accessorFn: (row) => {
        return row;
      },
      cell: ({ row }) => {
        return (
          <div className="text-muted-foreground text-center">
            {row.original.notContacted}
          </div>
        );
      },
    });

    cols.push({
      accessorKey: "status",
      header: () => {
        return <div className="text-center">Status</div>;
      },
      meta: "Status",
      accessorFn: (row) => {
        return row;
      },
      cell: ({ row }) => {
        return <JobStatusDropdown job={row.original} />;
      },
    });
    cols.push({
      accessorKey: "actions",
      header: () => {
        return <div className="text-end">Actions</div>;
      },
      meta: "Actions",
      accessorFn: (row) => {
        return row;
      },
      cell: ({ row }) => {
        const job = row.original;
        return (
          <ReviewButton
            jobId={job.id}
            numberReadyForReview={job.totalReadyForReview}
          />
        );
      },
    });
    return cols;
  }, [
    columnVisibility.companyName,
    columnVisibility.jobLocation,
    columnVisibility.createdAt,
    getDateLabel,
  ]);

  const table = useReactTable({
    data: jobs,
    columns,
    getCoreRowModel: getCoreRowModel(),
    manualSorting: true,
    onSortingChange: (updater) => {
      if (typeof updater !== "function") {
        return;
      }
      const newSorting = updater(sorting);

      router.replace(
        pathname +
          "?" +
          createQueryString([
            {
              name: "sorting",
              value: JSON.stringify(newSorting),
            },
            {
              name: "page",
              value: "1",
            },
          ]),
      );
    },
    manualPagination: true,
    pageCount: Math.ceil(totalCount / pagination.pageSize),
    onPaginationChange: (updater) => {
      if (typeof updater !== "function") {
        return;
      }
      const newPagination = updater(pagination);

      router.replace(
        pathname +
          "?" +
          createQueryString([
            {
              name: "page",
              value: (newPagination.pageIndex + 1).toString(),
            },
            {
              name: "pageSize",
              value: newPagination.pageSize.toString(),
            },
          ]),
      );
    },
    manualFiltering: true,
    onColumnFiltersChange: (updater) => {
      if (typeof updater !== "function") {
        return;
      }
      const newColumnFilters = updater(columnFilters);

      router.replace(
        pathname +
          "?" +
          createQueryString([
            {
              name: "columnFilters",
              value: JSON.stringify(newColumnFilters),
            },
            {
              name: "page",
              value: "1",
            },
          ]),
      );
    },
    onColumnVisibilityChange: setColumnVisibility,
    state: {
      columnFilters,
      pagination,
      sorting,
      columnVisibility,
    },
  });

  const isFiltered = table.getState().columnFilters.length > 0;

  return (
    <div className="mt-2 space-y-4">
      <div className="flex items-center gap-x-4">
        <div className="flex flex-1 items-center space-x-2">
          <Input
            type="text"
            placeholder="Search jobs, ATS ID, or Client ID..."
            defaultValue={query ?? ""}
            onChange={(e) => {
              debouncedOnQueryChange(e.target.value);
            }}
            className="max-w-sm"
          />
          {table.getColumn("status") && (
            <DataTableFacetedFilter
              column={table.getColumn("status")}
              title="Status"
              options={[
                {
                  label: "Draft",
                  value: "draft",
                },
                {
                  label: "Active",
                  value: JobStatus.ACTIVE,
                },
                {
                  label: "Paused",
                  value: JobStatus.PAUSED,
                },
                {
                  label: "Closed",
                  value: JobStatus.CLOSED,
                },
              ]}
            />
          )}
          {isFiltered && (
            <Button
              variant="ghost"
              onClick={() => {
                table.resetColumnFilters();
              }}
            >
              Reset
              <IconClose className="ml-2 h-4 w-4" />
            </Button>
          )}
        </div>
        <div>
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="outline" className="ml-auto">
                <IconTune className="mr-2 size-4" />
                Views
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end">
              {table
                .getAllColumns()
                .filter((column) => column.getCanHide())
                .map((column) => {
                  return (
                    <DropdownMenuCheckboxItem
                      key={column.id}
                      className="capitalize"
                      checked={column.getIsVisible()}
                      onCheckedChange={(value) =>
                        column.toggleVisibility(Boolean(value))
                      }
                    >
                      {(column.columnDef.meta as string) || column.id}
                    </DropdownMenuCheckboxItem>
                  );
                })}
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>
      <Table>
        <TableHeader>
          {table.getHeaderGroups().map((headerGroup) => (
            <TableRow key={headerGroup.id}>
              {headerGroup.headers.map((header) => {
                return (
                  <TableHead key={header.id} className="text-nowrap">
                    {header.isPlaceholder
                      ? null
                      : flexRender(
                          header.column.columnDef.header,
                          header.getContext(),
                        )}
                  </TableHead>
                );
              })}
            </TableRow>
          ))}
        </TableHeader>
        <TableBody>
          {table.getRowModel().rows.length ? (
            table.getRowModel().rows.map((row) => (
              <TableRow
                key={row.original.id}
                role="button"
                onClick={() => {
                  router.push(
                    `/organizations/${organizationId}/jobs/${row.original.id}/pipeline`,
                  );
                }}
              >
                {row.getVisibleCells().map((cell, i) => (
                  <TableCell
                    key={cell.id}
                    className={cn(i > 0 ? "w-fit" : "w-full")}
                  >
                    {flexRender(cell.column.columnDef.cell, cell.getContext())}
                  </TableCell>
                ))}
              </TableRow>
            ))
          ) : (
            <TableRow>
              <TableCell colSpan={columns.length} className="h-24 text-center">
                No results.
              </TableCell>
            </TableRow>
          )}
        </TableBody>
      </Table>
      <DataTablePagination table={table} totalCount={totalCount} />
      {jobs.length === 0 && (
        <p className="text-muted-foreground text-center">No jobs found.</p>
      )}
    </div>
  );
}

