import type { DraggableSyntheticListeners } from "@dnd-kit/core";
import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { type TemplateVariable } from "@purplefish-ai/db";
import IconAdd from "@purplefish-ai/material-icons/icons/icon-add";
import IconContentCopy from "@purplefish-ai/material-icons/icons/icon-content-copy";
import IconContentPaste from "@purplefish-ai/material-icons/icons/icon-content-paste";
import IconContentPasteOff from "@purplefish-ai/material-icons/icons/icon-content-paste-off";
import DragIndicator from "@purplefish-ai/material-icons/icons/icon-drag-indicator";
import IconSubdirectoryArrowLeft from "@purplefish-ai/material-icons/icons/icon-subdirectory-arrow-left";
import { Button } from "@purplefish-ai/shadcn-ui/components/ui/button";
import { cn } from "@purplefish-ai/shadcn-ui/utils/cn";
import debounce from "debounce";
import type { CSSProperties } from "react";
import React, {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useState,
} from "react";

import { getAllDescendants } from "@/common/libs/tree-utils";
import type { ScriptNode } from "@/common/models/script-nodes";

import SavingIndicator from "../saving-indicator";
import AddScriptNodeButton from "./add-script-node-button";
import { nodeContainsAutoPopulatedVariable } from "./call-builder-utils";
import DeleteScriptNode from "./delete-script-node";
import ScriptNodeDisplayContainer from "./script-node-container/script-node-display-container";
import ScriptNodeEditableContainer from "./script-node-container/script-node-editable-container";
import { TransitionCondition } from "./transition-condition";

interface Context {
  attributes: React.HTMLAttributes<HTMLElement>;
  listeners: DraggableSyntheticListeners;
  ref(this: void, node: HTMLElement | null): void;
}

const ScriptNodeItemContext = createContext<Context>({
  attributes: {},
  listeners: undefined,
  ref: () => void 0,
});

export function ScriptNodeItem({
  item,
  createItem,
  updateItem: updateItemCallback,
  deleteItem,
  updateActiveStates,
  systemTemplateVariables,
  autoPopulatedVariables = [],
  isTemplateMode,
  copiedNode,
  onCopy,
  onPaste,
  nodes,
  fallbackLanguage,
  isSystemAdmin,
}: {
  item: ScriptNode;
  createItem: ({
    sourceNode,
    isChild,
  }: {
    sourceNode: ScriptNode;
    isChild: boolean;
  }) => void;
  updateItem: (item: ScriptNode) => void;
  deleteItem: (id: string) => void;
  updateActiveStates: (id: string) => void;
  systemTemplateVariables: TemplateVariable[];
  autoPopulatedVariables?: TemplateVariable[];
  isTemplateMode: boolean;
  copiedNode: ScriptNode | null;
  onCopy: (node: ScriptNode) => void;
  onPaste: (node: ScriptNode) => void;
  nodes: ScriptNode[];
  fallbackLanguage: string;
  isSystemAdmin: boolean;
}) {
  const {
    attributes,
    isDragging,
    listeners,
    setNodeRef,
    setActivatorNodeRef,
    transform,
    transition,
  } = useSortable({ id: item.id });

  const [isSaving, setIsSaving] = useState(false);

  const indicateSaving = () => {
    setIsSaving(true);
    setTimeout(() => {
      setIsSaving(false);
    }, 1000);
  };

  const hasError = useMemo(() => {
    if (!autoPopulatedVariables.length) {
      return false;
    }

    return nodeContainsAutoPopulatedVariable(item, autoPopulatedVariables);
  }, [item, autoPopulatedVariables]);

  const updateItem = useMemo(
    () =>
      debounce(async (updatedNode: ScriptNode) => {
        indicateSaving();
        updateItemCallback(updatedNode);
      }, 1000),
    [updateItemCallback, indicateSaving],
  );

  const context = useMemo(
    () => ({
      attributes,
      listeners,
      ref: setActivatorNodeRef,
    }),
    [attributes, listeners, setActivatorNodeRef],
  );
  const style: CSSProperties = {
    opacity: isDragging ? 0.4 : undefined,
    transform: CSS.Translate.toString(transform),
    transition,
  };

  const isChild = (item.depth ?? 0) > 0;
  const isParent = !isChild;

  const addChild = (event: React.MouseEvent<HTMLButtonElement>) => {
    event.stopPropagation();
    createItem({
      sourceNode: item,
      isChild: true,
    });
  };

  const addSibling = (event: React.MouseEvent<HTMLButtonElement>) => {
    event.stopPropagation();
    createItem({
      sourceNode: item,
      isChild: false,
    });
  };

  const handleCopy = (event: React.MouseEvent<HTMLButtonElement>) => {
    event.stopPropagation();

    const descendantIds = getAllDescendants({
      nodes,
      nodeId: item.id,
      includeSelf: true,
    });

    const descendantNodes = nodes.filter((node) =>
      descendantIds.includes(node.id),
    );

    const parentChildMap = new Map<string, string>();
    descendantNodes.forEach((node) => {
      if (node.conditionToEnter?.scriptNodeId) {
        parentChildMap.set(node.id, node.conditionToEnter.scriptNodeId);
      }
    });

    const copiedNodeWithChildren = {
      ...item,
      _copiedChildren: descendantNodes
        .filter((node) => node.id !== item.id)
        .map((node) => ({
          ...node,
          _originalParentId: parentChildMap.get(node.id),
          conditionToEnter: node.conditionToEnter
            ? {
                scriptNodeId: "temp-parent-id",
                evaluationMatches: node.conditionToEnter.evaluationMatches,
              }
            : null,
        })),
    };

    onCopy(copiedNodeWithChildren);
  };

  const handlePaste = (event: React.MouseEvent<HTMLButtonElement>) => {
    event.stopPropagation();
    onPaste(item);
  };

  const handleClearClipboard = (event: React.MouseEvent<HTMLButtonElement>) => {
    event.stopPropagation();
    onCopy(null as unknown as ScriptNode);
  };

  const renderScriptNodeContainer = () =>
    item.active ? (
      <ScriptNodeEditableContainer
        item={item}
        updateItem={updateItem}
        systemTemplateVariables={systemTemplateVariables}
        isTemplateMode={isTemplateMode}
        isChild={isChild}
        fallbackLanguage={fallbackLanguage}
        isSystemAdmin={isSystemAdmin}
      />
    ) : (
      <ScriptNodeDisplayContainer
        item={item}
        systemTemplateVariables={systemTemplateVariables}
        isTemplateMode={isTemplateMode}
      />
    );

  return (
    <ScriptNodeItemContext.Provider value={context}>
      <li
        id={item.id}
        ref={setNodeRef}
        className={"list-none"}
        onClick={() => {
          const itemIdToUpdate = item.active ? "" : item.id;

          updateActiveStates(itemIdToUpdate);
        }}
        style={{
          ...style,
          marginLeft: `${(item.depth ?? 0) * 32}px`,
        }}
      >
        {isChild ? (
          <div style={{ marginLeft: "-16px" }}>
            <TransitionCondition
              item={item}
              updateItem={updateItem}
              systemTemplateVariables={systemTemplateVariables}
              isTemplateMode={isTemplateMode}
            />
          </div>
        ) : (
          <div className="h-3"></div>
        )}
        <div className="flex flex-row">
          <div
            className={cn(
              "rounded-8 group relative box-border flex w-full cursor-pointer flex-row items-center rounded-md border p-2 shadow",
              item.active ? "border-purple-300" : "border-gray-300",
              hasError && "border-destructive",
            )}
            style={{ borderRadius: "4px" }}
          >
            <div className="absolute right-4 top-2">
              {isSaving && <SavingIndicator />}
            </div>
            <div className="ml-2 mr-4">{isChild ? <></> : <DragHandle />}</div>
            {renderScriptNodeContainer()}
            <div className="flex flex-row opacity-0 transition-opacity group-hover:opacity-100">
              {isParent && (
                <>
                  {copiedNode ? (
                    <Button
                      variant="ghost"
                      size="icon"
                      onClick={handleClearClipboard}
                    >
                      <IconContentPasteOff className="h-5 w-5" />
                    </Button>
                  ) : (
                    <Button variant="ghost" size="icon" onClick={handleCopy}>
                      <IconContentCopy className="h-5 w-5" />
                    </Button>
                  )}
                  {copiedNode && (
                    <Button variant="ghost" size="icon" onClick={handlePaste}>
                      <IconContentPaste className="h-5 w-5" />
                    </Button>
                  )}
                </>
              )}
              <DeleteScriptNode deleteItem={() => deleteItem(item.id)} />
            </div>
          </div>
          <div className="ml-2 flex flex-col self-center">
            {item.depth === 0 && (
              <AddScriptNodeButton onClick={addSibling} Icon={IconAdd} />
            )}
            <AddScriptNodeButton
              onClick={addChild}
              Icon={IconSubdirectoryArrowLeft}
            />
          </div>
        </div>
      </li>
    </ScriptNodeItemContext.Provider>
  );
}

function DragHandle() {
  const context = useContext(ScriptNodeItemContext);

  const { attributes, listeners, ref: contextRef } = context;

  const handleRef = useCallback(
    (node: HTMLElement | null) => {
      if (typeof contextRef === "function") {
        contextRef(node);
      }
    },
    [contextRef],
  );

  return (
    <button
      className="cursor-grabbing"
      {...attributes}
      {...listeners}
      ref={handleRef}
    >
      <DragIndicator className="text-muted-foreground h-4 w-4" />
    </button>
  );
}

