"use client";

import type { DraggableSyntheticListeners } from "@dnd-kit/core";
import IconCheck from "@purplefish-ai/material-icons/icons/icon-check";
import IconChevronDown from "@purplefish-ai/material-icons/icons/icon-chevron-down";
import IconDelete from "@purplefish-ai/material-icons/icons/icon-delete";
import IconDragIndicator from "@purplefish-ai/material-icons/icons/icon-drag-indicator";
import IconStar from "@purplefish-ai/material-icons/icons/icon-star";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@purplefish-ai/shadcn-ui/components/ui/alert-dialog";
import { Button } from "@purplefish-ai/shadcn-ui/components/ui/button";
import { Checkbox } from "@purplefish-ai/shadcn-ui/components/ui/checkbox";
import { Input } from "@purplefish-ai/shadcn-ui/components/ui/input";
import { Label } from "@purplefish-ai/shadcn-ui/components/ui/label";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@purplefish-ai/shadcn-ui/components/ui/popover";
import {
  RadioGroup,
  RadioGroupItem,
} from "@purplefish-ai/shadcn-ui/components/ui/radio-group";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@purplefish-ai/shadcn-ui/components/ui/select";
import { cn } from "@purplefish-ai/shadcn-ui/utils/cn";
import { useEffect, useRef, useState } from "react";

import { type ScorecardRequirement } from "@/common/models/interview-builder";
import {
  operatorsByType,
  type RequirementProperty,
} from "@/common/models/job-requirements";

import { DatePickerWithQuickOptions } from "../date-picker-with-quick-options";
import { validateRequirementProperties } from "../utils/requirement-validation";

interface JsonSchemaProperty {
  title?: string;
  type?: string;
  format?: string;
  enum?: string[];
}

interface JsonSchema {
  type?: string;
  format?: string;
  properties?: Record<string, JsonSchemaProperty>;
  required?: string[];
}

interface DataPointSchema {
  key: string;
  label: string;
  type: "number" | "string" | "boolean";
  jsonSchema?: JsonSchema;
}

interface RequirementCardProps {
  requirement: ScorecardRequirement;
  isActive: boolean;
  dataPoints: DataPointSchema[];
  onToggleActive: () => void;
  onUpdate: (requirement: ScorecardRequirement) => void;
  onDelete: () => void;
  onValidationChange?: (requirementId: string, hasErrors: boolean) => void;
  dragHandleProps?: React.HTMLAttributes<HTMLDivElement> &
    DraggableSyntheticListeners;
}

interface PropertyInfo {
  path: string;
  label: string;
  type: "string" | "number" | "boolean" | "enum" | "date";
  required: boolean;
  enum?: string[];
}

// Helper to extract property information from JSON schema
function extractProperties(jsonSchema: JsonSchema | undefined): PropertyInfo[] {
  if (!jsonSchema) {
    return [];
  }
  const schema = jsonSchema;

  if (!schema.properties) {
    // Simple schema without properties - use root
    return [
      {
        path: "",
        label: "Value",
        type: mapJsonSchemaType(
          schema.type ?? "string",
          undefined,
          schema.format,
        ),
        required: true,
      },
    ];
  }

  const properties: PropertyInfo[] = [];
  const required = schema.required ?? [];

  for (const [key, propSchema] of Object.entries(schema.properties)) {
    const prop = propSchema;
    properties.push({
      path: key,
      label: prop.title ?? key,
      type: mapJsonSchemaType(prop.type ?? "string", prop.enum, prop.format),
      required: required.includes(key),
      enum: prop.enum,
    });
  }

  return properties;
}

function mapJsonSchemaType(
  type: string,
  enumValues?: string[],
  format?: string,
): "string" | "number" | "boolean" | "enum" | "date" {
  if (enumValues && enumValues.length > 0) {
    return "enum";
  }
  if (type === "number" || type === "integer") {
    return "number";
  }
  if (type === "boolean") {
    return "boolean";
  }
  if (type === "string") {
    // Check for date/date-time format
    if (format === "date" || format === "date-time") {
      return "date";
    }
    return "string";
  }
  return "string";
}

function getOperatorLabel(operator: string): string {
  const operatorMap: Record<string, string> = {
    eq: "is",
    neq: "is not",
    gt: "is greater than",
    gte: "is at least",
    lt: "is less than",
    lte: "is at most",
    contains: "contains",
    starts_with: "starts with",
    ends_with: "ends with",
    regex: "matches pattern",
    in: "is one of",
    not_in: "is not one of",
    before: "is before",
    after: "is after",
    between: "is between",
    not_between: "is not between",
    hasValue: "has value",
  };
  return operatorMap[operator] ?? operator;
}

function formatDateValue(value: unknown): string {
  if (Array.isArray(value)) {
    // For between/not_between operators
    return value.map((v) => formatDateValue(v)).join(" and ");
  }
  if (typeof value === "string" && value) {
    const date = new Date(value);
    if (!isNaN(date.getTime())) {
      return date.toLocaleDateString();
    }
  }
  return String(value) || "";
}

export function RequirementCard({
  requirement,
  isActive,
  dataPoints,
  onToggleActive,
  onUpdate,
  onDelete,
  onValidationChange,
  dragHandleProps,
}: RequirementCardProps) {
  const [localRequirement, setLocalRequirement] =
    useState<ScorecardRequirement>(requirement);
  const [validationErrors, setValidationErrors] = useState<
    Record<number, string>
  >({});
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const cardRef = useRef<HTMLDivElement>(null);

  // Update local state when requirement prop changes
  useEffect(() => {
    setLocalRequirement(requirement);
  }, [requirement]);

  // Handle click outside to close the card
  useEffect(() => {
    if (!isActive) {
      return;
    }

    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as Node;

      // Don't close if clicking inside the card
      if (cardRef.current?.contains(target)) {
        return;
      }

      // Don't close if clicking on a portal element (dropdowns, popovers, etc.)
      const portalElements = document.querySelectorAll(
        '[data-radix-popper-content-wrapper], [role="dialog"], [role="alertdialog"]',
      );
      for (const element of portalElements) {
        if (element.contains(target)) {
          return;
        }
      }

      onToggleActive();
    };

    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [isActive, onToggleActive]);

  const candidateDataPoint = localRequirement.candidateDataPoint;
  const dataPoint = dataPoints.find(
    (dp) => dp.key === candidateDataPoint.schemaKey,
  );

  const schemaProperties = dataPoint?.jsonSchema
    ? extractProperties(dataPoint.jsonSchema)
    : [];

  // Validation function for properties
  const validateProperties = (properties: RequirementProperty[]) => {
    const errors = validateRequirementProperties(properties);
    setValidationErrors(errors);
    return Object.keys(errors).length === 0;
  };

  // Validate whenever requirement changes
  useEffect(() => {
    validateProperties(localRequirement.candidateDataPoint.properties);
  }, [localRequirement.candidateDataPoint.properties, validateProperties]);

  // Notify parent about validation state changes
  useEffect(() => {
    const hasErrors = Object.keys(validationErrors).length > 0;
    onValidationChange?.(requirement.id, hasErrors);
  }, [validationErrors, requirement.id, onValidationChange]);

  const handlePropertyChange = (
    index: number,
    field: keyof RequirementProperty,
    value: unknown,
  ) => {
    const updatedProperties = [...candidateDataPoint.properties];
    const currentProp = updatedProperties[index];

    if (!currentProp) {
      return;
    }

    // If changing operator to "hasValue", clear the value
    if (field === "operator" && value === "hasValue") {
      updatedProperties[index] = {
        ...currentProp,
        operator: value as RequirementProperty["operator"],
        value: "",
      } as RequirementProperty;
    }
    // If changing operator to "in" or "not_in", initialize value as empty array
    else if (field === "operator" && (value === "in" || value === "not_in")) {
      updatedProperties[index] = {
        ...currentProp,
        operator: value as RequirementProperty["operator"],
        value: Array.isArray(currentProp.value) ? currentProp.value : [],
      } as RequirementProperty;
    }
    // If changing operator to "between" or "not_between", initialize value as array with two values
    else if (
      field === "operator" &&
      (value === "between" || value === "not_between")
    ) {
      let newValue: unknown[];
      if (currentProp.type === "date") {
        // For dates, initialize with today and a month from now
        const today = new Date();
        const nextMonth = new Date(today);
        nextMonth.setMonth(nextMonth.getMonth() + 1);

        if (Array.isArray(currentProp.value)) {
          newValue = currentProp.value;
        } else if (typeof currentProp.value === "string" && currentProp.value) {
          // If switching from single date, use it as start and add a month for end
          const startDate = new Date(currentProp.value);
          const endDate = new Date(startDate);
          endDate.setMonth(endDate.getMonth() + 1);
          newValue = [startDate.toISOString(), endDate.toISOString()];
        } else {
          newValue = [today.toISOString(), nextMonth.toISOString()];
        }
      } else {
        newValue =
          Array.isArray(currentProp.value) && currentProp.value.length === 2
            ? currentProp.value
            : ["", ""];
      }

      updatedProperties[index] = {
        ...currentProp,
        operator: value as RequirementProperty["operator"],
        value: newValue,
      } as RequirementProperty;
    }
    // If changing operator from "in" or "not_in" to something else, convert array to single value
    else if (
      field === "operator" &&
      (currentProp.operator === "in" || currentProp.operator === "not_in") &&
      value !== "in" &&
      value !== "not_in"
    ) {
      updatedProperties[index] = {
        ...currentProp,
        operator: value as RequirementProperty["operator"],
        value:
          Array.isArray(currentProp.value) &&
          (currentProp.value as unknown[]).length > 0
            ? (currentProp.value as unknown[])[0]
            : "",
      } as RequirementProperty;
    }
    // If changing operator from "between" or "not_between" to something else, convert array to single value
    else if (
      field === "operator" &&
      (currentProp.operator === "between" ||
        currentProp.operator === "not_between") &&
      value !== "between" &&
      value !== "not_between"
    ) {
      // Convert array to single value
      let newValue: unknown = "";

      if (Array.isArray(currentProp.value) && currentProp.value[0]) {
        newValue = currentProp.value[0];
      } else {
        // For date types with no value, default to today's date
        newValue = new Date().toISOString();
      }

      updatedProperties[index] = {
        ...currentProp,
        operator: value as RequirementProperty["operator"],
        value: newValue,
      } as RequirementProperty;
    } else {
      updatedProperties[index] = {
        ...currentProp,
        [field]: value,
      } as RequirementProperty;
    }

    const updated = {
      ...localRequirement,
      candidateDataPoint: {
        ...candidateDataPoint,
        properties: updatedProperties,
      },
    };
    setLocalRequirement(updated);
    onUpdate(updated);
  };

  const handleTypeChange = (type: "mandatory" | "preferred") => {
    const updated = {
      ...localRequirement,
      type,
    };
    setLocalRequirement(updated);
    onUpdate(updated);
  };

  const handleDeleteClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    setShowDeleteConfirm(true);
  };

  const handleConfirmDelete = () => {
    setShowDeleteConfirm(false);
    onDelete();
  };

  // Display mode (collapsed)
  if (!isActive) {
    const hasErrors = Object.keys(validationErrors).length > 0;

    return (
      <>
        <div
          className={cn(
            "group relative flex cursor-pointer items-center rounded-md border p-3 transition-colors hover:bg-gray-50 dark:hover:bg-gray-800",
            hasErrors
              ? "border-red-500 dark:border-red-500"
              : "border-gray-200 dark:border-gray-700",
          )}
          onClick={onToggleActive}
        >
          <div
            className="mr-3 cursor-grab opacity-0 transition-opacity group-hover:opacity-100"
            {...dragHandleProps}
          >
            <IconDragIndicator className="h-5 w-5 text-gray-400" />
          </div>

          <div className="mr-3">
            {localRequirement.type === "mandatory" ? (
              <IconCheck className="h-5 w-5 text-green-600" />
            ) : (
              <IconStar className="h-5 w-5 text-yellow-600" />
            )}
          </div>

          <div className="flex flex-1 items-center justify-between pr-10">
            <div className="flex-1">
              {dataPoint && candidateDataPoint.properties.length > 0 ? (
                <div className="text-sm">
                  <span className="font-medium">{dataPoint.label}</span>
                  <div className="mt-1 text-xs text-gray-500">
                    {candidateDataPoint.properties.map((prop, idx) => {
                      const propSchema = schemaProperties.find(
                        (p) => p.path === prop.path,
                      );
                      const propIndex =
                        candidateDataPoint.properties.indexOf(prop);
                      const hasError = validationErrors[propIndex];
                      const label = propSchema?.label || prop.path || "Value";
                      const valueDisplay =
                        prop.type === "boolean"
                          ? prop.value
                            ? "Yes"
                            : "No"
                          : prop.type === "date"
                            ? formatDateValue(prop.value)
                            : Array.isArray(prop.value)
                              ? prop.value.join(", ")
                              : String(prop.value);

                      return (
                        <div
                          key={idx}
                          className={hasError ? "text-red-500" : ""}
                        >
                          <span className="font-semibold">{label}</span>{" "}
                          {hasError ? (
                            <span className="italic">requires a value</span>
                          ) : prop.operator === "hasValue" ? (
                            <span>{getOperatorLabel(prop.operator)}</span>
                          ) : (
                            <>
                              {getOperatorLabel(prop.operator)} {valueDisplay}
                            </>
                          )}
                        </div>
                      );
                    })}
                  </div>
                </div>
              ) : (
                <span className="text-sm text-red-500">
                  Click to configure requirement
                </span>
              )}
            </div>
          </div>

          <Button
            onClick={handleDeleteClick}
            variant="ghost"
            size="icon"
            className="absolute right-2 top-1/2 h-8 w-8 -translate-y-1/2 opacity-0 transition-opacity group-hover:opacity-100"
          >
            <IconDelete className="h-4 w-4 text-red-500" />
          </Button>
        </div>

        {/* Delete Confirmation Dialog */}
        <AlertDialog
          open={showDeleteConfirm}
          onOpenChange={setShowDeleteConfirm}
        >
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Delete Requirement</AlertDialogTitle>
              <AlertDialogDescription>
                Are you sure you want to delete this requirement? This action
                cannot be undone.
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>Cancel</AlertDialogCancel>
              <AlertDialogAction
                onClick={handleConfirmDelete}
                className="bg-red-600 hover:bg-red-700"
              >
                Delete
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      </>
    );
  }

  // Edit mode (expanded)
  return (
    <>
      <div
        ref={cardRef}
        className="relative rounded-md border-2 border-purple-300 p-4 dark:border-purple-700"
      >
        {/* Delete and Collapse buttons at top right */}
        <div className="absolute right-2 top-2 flex gap-1">
          <Button
            onClick={handleDeleteClick}
            variant="ghost"
            size="icon"
            className="h-8 w-8 text-red-600 hover:text-red-700 dark:text-red-400 dark:hover:text-red-300"
          >
            <IconDelete className="h-4 w-4" />
          </Button>
          <Button
            onClick={onToggleActive}
            variant="ghost"
            size="icon"
            className="h-8 w-8 text-gray-600 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-300"
          >
            <IconChevronDown className="h-4 w-4" />
          </Button>
        </div>

        <div className="space-y-4">
          {/* Requirement Title with End Call Icon */}
          <div className="space-y-2">
            <div className="flex items-center gap-2">
              <Label htmlFor="name">Requirement Name</Label>
            </div>
            <Input
              id="name"
              value={localRequirement.name}
              onChange={(e) => {
                const updated = { ...localRequirement, name: e.target.value };
                setLocalRequirement(updated);
                onUpdate(updated);
              }}
              placeholder="e.g., Years of Experience"
              className="w-full"
            />
          </div>

          {/* Property Requirements */}
          {candidateDataPoint.schemaKey &&
          candidateDataPoint.properties.length > 0 ? (
            <div className="space-y-3">
              {/* Column headers - show only once */}
              <div className="text-xs font-medium text-gray-600 dark:text-gray-400">
                Validation Conditions
              </div>

              {/* Sort properties: required first, then non-required */}
              {[...candidateDataPoint.properties]
                .sort((a, b) => {
                  if (a.required && !b.required) {
                    return -1;
                  }
                  if (!a.required && b.required) {
                    return 1;
                  }
                  return 0;
                })
                .map((prop) => {
                  // Find the actual index in the original properties array
                  const index = candidateDataPoint.properties.indexOf(prop);
                  const propSchema = schemaProperties.find(
                    (p) => p.path === prop.path,
                  );
                  const label = propSchema?.label ?? (prop.path || "Value");
                  const availableOperators = operatorsByType[prop.type];

                  // All properties are included

                  return (
                    <div key={index} className="space-y-2">
                      <div className="flex items-start gap-2">
                        {/* Property name in fixed width input */}
                        <Input
                          value={label}
                          disabled
                          className="h-10 w-[200px] text-sm font-medium disabled:text-gray-900 disabled:opacity-100 dark:disabled:text-gray-100"
                        />

                        {/* Operator Selection */}
                        <Select
                          value={prop.operator}
                          onValueChange={(value) =>
                            handlePropertyChange(index, "operator", value)
                          }
                        >
                          <SelectTrigger className="h-10 w-[200px] text-left">
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            {availableOperators.map((op) => (
                              <SelectItem key={op} value={op}>
                                {getOperatorLabel(op)}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>

                        {/* Value Input - Hide for hasValue operator */}
                        {prop.operator !== "hasValue" && (
                          <div className="flex w-[200px] flex-col">
                            {prop.type === "boolean" ? (
                              <Select
                                value={String(prop.value)}
                                onValueChange={(value) =>
                                  handlePropertyChange(
                                    index,
                                    "value",
                                    value === "true",
                                  )
                                }
                              >
                                <SelectTrigger className="h-10 text-left">
                                  <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                  <SelectItem value="true">Yes</SelectItem>
                                  <SelectItem value="false">No</SelectItem>
                                </SelectContent>
                              </Select>
                            ) : prop.type === "enum" && propSchema?.enum ? (
                              // Multi-select for "in" and "not_in" operators
                              prop.operator === "in" ||
                              prop.operator === "not_in" ? (
                                <Popover>
                                  <PopoverTrigger asChild>
                                    <Button
                                      variant="outline"
                                      className="h-10 w-full justify-start"
                                    >
                                      {Array.isArray(prop.value) &&
                                      prop.value.length > 0
                                        ? `${prop.value.length} selected`
                                        : "Select values..."}
                                    </Button>
                                  </PopoverTrigger>
                                  <PopoverContent
                                    className="w-[200px] p-0"
                                    align="start"
                                  >
                                    <div className="max-h-[300px] overflow-auto p-2">
                                      {propSchema.enum.map((val) => {
                                        const isSelected =
                                          Array.isArray(prop.value) &&
                                          prop.value.includes(val);
                                        return (
                                          <div
                                            key={val}
                                            className="flex cursor-pointer items-center space-x-2 rounded px-2 py-1.5 hover:bg-gray-100 dark:hover:bg-gray-800"
                                            onClick={() => {
                                              const currentValues =
                                                Array.isArray(prop.value)
                                                  ? prop.value
                                                  : [];
                                              const newValues = isSelected
                                                ? currentValues.filter(
                                                    (v) => v !== val,
                                                  )
                                                : [...currentValues, val];
                                              handlePropertyChange(
                                                index,
                                                "value",
                                                newValues,
                                              );
                                            }}
                                          >
                                            <Checkbox checked={isSelected} />
                                            <Label className="cursor-pointer font-normal">
                                              {val}
                                            </Label>
                                          </div>
                                        );
                                      })}
                                    </div>
                                  </PopoverContent>
                                </Popover>
                              ) : (
                                <Select
                                  value={
                                    prop.value === ""
                                      ? undefined
                                      : String(prop.value)
                                  }
                                  onValueChange={(value) =>
                                    handlePropertyChange(index, "value", value)
                                  }
                                  disabled={false}
                                >
                                  <SelectTrigger className="h-10 text-left">
                                    <SelectValue placeholder="Select a value..." />
                                  </SelectTrigger>
                                  <SelectContent>
                                    {propSchema.enum.map((val) => (
                                      <SelectItem key={val} value={val}>
                                        {val}
                                      </SelectItem>
                                    ))}
                                  </SelectContent>
                                </Select>
                              )
                            ) : prop.type === "date" ? (
                              // Date picker for date properties
                              prop.operator === "between" ||
                              prop.operator === "not_between" ? (
                                <div className="flex flex-1 gap-2">
                                  <DatePickerWithQuickOptions
                                    value={
                                      Array.isArray(prop.value) && prop.value[0]
                                        ? prop.value[0]
                                        : undefined
                                    }
                                    onValueChange={(date) => {
                                      const currentValues = Array.isArray(
                                        prop.value,
                                      )
                                        ? prop.value
                                        : ["", ""];
                                      handlePropertyChange(index, "value", [
                                        date,
                                        currentValues[1] ?? "",
                                      ]);
                                    }}
                                    placeholder="Start date"
                                  />
                                  <DatePickerWithQuickOptions
                                    value={
                                      Array.isArray(prop.value) && prop.value[1]
                                        ? prop.value[1]
                                        : undefined
                                    }
                                    onValueChange={(date) => {
                                      const currentValues = Array.isArray(
                                        prop.value,
                                      )
                                        ? prop.value
                                        : ["", ""];
                                      handlePropertyChange(index, "value", [
                                        currentValues[0] ?? "",
                                        date,
                                      ]);
                                    }}
                                    placeholder="End date"
                                  />
                                </div>
                              ) : (
                                <DatePickerWithQuickOptions
                                  value={
                                    typeof prop.value === "string"
                                      ? prop.value
                                      : undefined
                                  }
                                  onValueChange={(date) =>
                                    handlePropertyChange(index, "value", date)
                                  }
                                  placeholder="Select date"
                                />
                              )
                            ) : (
                              <Input
                                className="h-10 text-left"
                                type={
                                  prop.type === "number" ? "number" : "text"
                                }
                                value={
                                  prop.value === "" ? "" : String(prop.value)
                                }
                                onChange={(e) =>
                                  handlePropertyChange(
                                    index,
                                    "value",
                                    prop.type === "number"
                                      ? e.target.value === ""
                                        ? ""
                                        : Number(e.target.value)
                                      : e.target.value,
                                  )
                                }
                                placeholder={
                                  prop.type === "number"
                                    ? "Enter a number..."
                                    : "Enter a value..."
                                }
                              />
                            )}
                            {validationErrors[index] && (
                              <p className="mt-1 text-xs text-red-500">
                                {validationErrors[index]}
                              </p>
                            )}
                          </div>
                        )}
                      </div>
                    </div>
                  );
                })}
            </div>
          ) : null}

          {/* Requirement Type */}
          <div className="space-y-3">
            <Label>Requirement Type</Label>
            <RadioGroup
              value={localRequirement.type}
              onValueChange={(val) =>
                handleTypeChange(val as "mandatory" | "preferred")
              }
            >
              <div className="flex items-center space-x-3 py-1">
                <RadioGroupItem
                  value="mandatory"
                  id="mandatory"
                  className="border-purple-300 text-purple-600 data-[state=checked]:border-purple-600 data-[state=checked]:text-purple-600"
                />
                <Label
                  htmlFor="mandatory"
                  className="flex cursor-pointer items-center gap-2 font-normal"
                >
                  <IconCheck className="h-4 w-4 text-green-600" />
                  <span className="font-medium">Mandatory</span>
                  <span className="text-sm text-gray-500">
                    - Candidate must meet this requirement
                  </span>
                </Label>
              </div>
              <div className="flex items-center space-x-3 py-1">
                <RadioGroupItem
                  value="preferred"
                  id="preferred"
                  className="border-purple-300 text-purple-600 data-[state=checked]:border-purple-600 data-[state=checked]:text-purple-600"
                />
                <Label
                  htmlFor="preferred"
                  className="flex cursor-pointer items-center gap-2 font-normal"
                >
                  <IconStar className="h-4 w-4 text-yellow-600" />
                  <span className="font-medium">Preferred</span>
                  <span className="text-sm text-gray-500">
                    - Nice to have, but not required
                  </span>
                </Label>
              </div>
            </RadioGroup>
          </div>
        </div>
      </div>

      {/* Delete Confirmation Dialog */}
      <AlertDialog open={showDeleteConfirm} onOpenChange={setShowDeleteConfirm}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Requirement</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete this requirement? This action
              cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleConfirmDelete}
              className="bg-red-600 hover:bg-red-700"
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

