"use client";

import type { User } from "@purplefish-ai/db";
import IconAdd from "@purplefish-ai/material-icons/icons/icon-add";
import IconCheck from "@purplefish-ai/material-icons/icons/icon-check";
import IconEdit from "@purplefish-ai/material-icons/icons/icon-edit";
import { Badge } from "@purplefish-ai/shadcn-ui/components/ui/badge";
import { Button } from "@purplefish-ai/shadcn-ui/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@purplefish-ai/shadcn-ui/components/ui/select";
import { Textarea } from "@purplefish-ai/shadcn-ui/components/ui/textarea";
import { cn } from "@purplefish-ai/shadcn-ui/utils/cn";
import { useMutation, useQuery } from "@tanstack/react-query";
import { useMemo, useState } from "react";
import { toast } from "sonner";

import {
  engagementFlagCategories,
  engagementFlagResolutionCategories,
} from "@/common/models/engagement-flags";
import { SidePanel } from "@/components/side-panel/side-panel";
import { useOrganizationContext } from "@/contexts/organization-context";
import type { EngagementFlagWithUsers } from "@/server/libs/engagement-flags";
import { useTRPC } from "@/trpc/client";

type EngagementFlagCategory = keyof typeof engagementFlagCategories;
type EngagementFlagResolutionCategory =
  keyof typeof engagementFlagResolutionCategories;

export function SidePanelEngagementFlags({
  children,
  engagementId,
}: {
  children: React.ReactNode;
  engagementId: string;
}) {
  const { organizationId } = useOrganizationContext();
  const trpc = useTRPC();

  const { data: engagementFlags = [], refetch } = useQuery(
    trpc.engagementFlag.getEngagementFlags.queryOptions({
      organizationId,
      engagementId,
    }),
  );

  const { mutate: createEngagementFlag, isPending: isCreatingEngagementFlag } =
    useMutation(trpc.engagementFlag.createEngagementFlag.mutationOptions());

  const { mutate: updateEngagementFlag, isPending: isUpdatingEngagementFlag } =
    useMutation(trpc.engagementFlag.updateEngagementFlag.mutationOptions());

  const {
    mutate: resolveEngagementFlag,
    isPending: isResolvingEngagementFlag,
  } = useMutation(trpc.engagementFlag.resolveEngagementFlag.mutationOptions());

  const sortFlags = (
    flags: EngagementFlagWithUsers[],
    sortKey: "createdAt" | "resolvedAt",
  ) => {
    return [...flags].sort((a, b) => {
      if (a[sortKey] && b[sortKey]) {
        return a[sortKey].getTime() - b[sortKey].getTime();
      }
      return 0;
    });
  };

  const flags = useMemo(
    () =>
      sortFlags(
        engagementFlags.filter((flag) => !flag.resolvedAt),
        "createdAt",
      ),
    [engagementFlags, sortFlags],
  );

  const resolvedFlags = useMemo(
    () =>
      sortFlags(
        engagementFlags.filter((flag) => flag.resolvedAt),
        "resolvedAt",
      ),
    [engagementFlags, sortFlags],
  );

  const [newFlagText, setNewFlagText] = useState("");
  const [selectedCategory, setSelectedCategory] = useState<
    EngagementFlagCategory | ""
  >("");

  const [showAddForm, setShowAddForm] = useState(false);
  const [editingFlagId, setEditingFlagId] = useState<string | null>(null);
  const [resolvingFlagId, setResolvingFlagId] = useState<string | null>(null);
  const [resolutionReason, setResolutionReason] = useState("");
  const [resolutionCategory, setResolutionCategory] = useState<
    EngagementFlagResolutionCategory | ""
  >("");

  const handleAddOrUpdateFlag = () => {
    if (newFlagText.trim() === "" || !selectedCategory) {
      return;
    }

    if (editingFlagId) {
      updateEngagementFlag(
        {
          organizationId,
          engagementFlagId: editingFlagId,
          notes: newFlagText,
          category: selectedCategory,
        },
        {
          onSuccess: () => {
            refetch()
              .then(() => {
                resetForm();
              })
              .catch(console.error);
          },
          onError: () => {
            toast.error("Failed to update flag");
          },
        },
      );
    } else {
      createEngagementFlag(
        {
          organizationId,
          engagementId,
          notes: newFlagText,
          category: selectedCategory,
        },
        {
          onSuccess: () => {
            refetch()
              .then(() => {
                resetForm();
              })
              .catch(console.error);
          },
          onError: () => {
            toast.error("Failed to add flag");
          },
        },
      );
    }
  };

  const handleEditFlag = (flag: EngagementFlagWithUsers) => {
    resetForm();

    setEditingFlagId(flag.id);
    setNewFlagText(flag.notes ?? "");
    setSelectedCategory(flag.category as EngagementFlagCategory);
  };

  const initiateResolution = (id: string) => {
    resetForm();

    setResolvingFlagId(id);
    setResolutionReason("");
    setResolutionCategory("");
  };

  const confirmResolution = () => {
    if (
      !resolvingFlagId ||
      !resolutionCategory ||
      resolutionReason.trim() === ""
    ) {
      return;
    }

    resolveEngagementFlag(
      {
        organizationId,
        engagementFlagId: resolvingFlagId,
        resolutionNotes: resolutionReason,
        resolutionCategory,
      },
      {
        onSuccess: () => {
          toast.success("Flag resolved");
          refetch()
            .then(() => {
              resetForm();

              // Reset removal state
              setResolvingFlagId(null);
              setResolutionReason("");
              setResolutionCategory("");
            })
            .catch(console.error);
        },
        onError: () => {
          toast.error("Failed to resolve flag");
        },
      },
    );
  };

  const resetForm = () => {
    setNewFlagText("");
    setSelectedCategory("");
    setEditingFlagId(null);
    setResolvingFlagId(null);
    setResolutionReason("");
    setResolutionCategory("");
    setShowAddForm(false);
  };

  const handleOpenNewFlagForm = () => {
    resetForm();
    setShowAddForm(true);
  };

  // first name and last initial
  const getDisplayName = (user: User) => {
    return `${user.firstName} ${user.lastName?.charAt(0)}`;
  };

  // Get array of tags that are already used
  const usedCategories = flags
    .filter((flag) => flag.id !== editingFlagId)
    .map((flag) => flag.category);

  const flagCategorySelect = (
    <Select
      value={selectedCategory}
      onValueChange={(value) =>
        setSelectedCategory(value as EngagementFlagCategory)
      }
    >
      <SelectTrigger>
        <SelectValue placeholder="Select a category" />
      </SelectTrigger>
      <SelectContent>
        {Object.entries(engagementFlagCategories).map(
          ([value, { label, icon: TagIcon, description }]) => {
            const isUsed = usedCategories.includes(
              value as EngagementFlagCategory,
            );
            return (
              <SelectItem
                key={value}
                value={value}
                disabled={isUsed}
                className={isUsed ? "opacity-50" : ""}
              >
                <div className="flex items-center gap-2">
                  <TagIcon className="mr-2 h-5 w-5" />
                  <div className="flex flex-col text-left">
                    {label} {isUsed && " (already used)"}
                    <div className="text-muted-foreground text-xs">
                      {description}
                    </div>
                  </div>
                </div>
              </SelectItem>
            );
          },
        )}
      </SelectContent>
    </Select>
  );

  const renderFlags = (flags: EngagementFlagWithUsers[]) =>
    flags.map((flag) => {
      const FlagIcon: React.ComponentType<{ className?: string }> =
        engagementFlagCategories[
          flag.category as keyof typeof engagementFlagCategories
        ].icon;
      const isResolved = flag.resolvedAt;
      const isEditing = editingFlagId === flag.id;
      const isResolving = resolvingFlagId === flag.id;

      return (
        <div
          key={flag.id}
          className={cn(
            "relative rounded-md border border-gray-300 p-3 shadow",
            isEditing && "border-purple-300",
            isResolving && "border-purple-300",
            isResolved && "bg-muted",
          )}
        >
          {!isEditing && !isResolving && (
            <>
              <div className="mb-2 flex flex-wrap items-start gap-2 pr-14">
                <Badge variant="outline" className="flex items-center gap-1">
                  <FlagIcon className="h-3 w-3" />
                  {
                    engagementFlagCategories[
                      flag.category as keyof typeof engagementFlagCategories
                    ].label
                  }
                </Badge>
              </div>
              {!isResolved && (
                <div className="absolute right-2 top-2 flex gap-1">
                  <Button
                    variant="ghost"
                    size="icon"
                    className="text-muted-foreground hover:text-foreground h-5 w-5"
                    onClick={() => handleEditFlag(flag)}
                  >
                    <IconEdit className="h-4 w-4" />
                    <span className="sr-only">Edit</span>
                  </Button>
                  <Button
                    variant="ghost"
                    size="icon"
                    className="text-muted-foreground hover:text-foreground h-5 w-5"
                    onClick={() => initiateResolution(flag.id)}
                  >
                    <IconCheck className="h-6 w-6" />
                    <span className="sr-only">Resolve</span>
                  </Button>
                </div>
              )}
              <p className="text-sm">{flag.notes}</p>
              <p className="text-muted-foreground mt-2 text-xs">
                Trained by {getDisplayName(flag.createdBy)} on{" "}
                {flag.createdAt.toLocaleString()}
              </p>
              {isResolved && (
                <div className="mt-2 border-t border-gray-300 pt-2">
                  <div className="text-muted-foreground flex flex-row items-center gap-2 text-sm">
                    <span className="font-medium">Resolution:</span>{" "}
                    <Badge
                      variant="outline"
                      className={cn("flex items-center gap-1")}
                    >
                      <FlagIcon className="h-3 w-3" />
                      {
                        engagementFlagResolutionCategories[
                          flag.resolutionCategory as keyof typeof engagementFlagResolutionCategories
                        ].label
                      }
                    </Badge>
                  </div>
                  <p className="text-sm italic">{flag.resolutionNotes}</p>
                  {flag.resolvedBy && (
                    <p className="text-muted-foreground mt-2 text-xs">
                      Resolved by {getDisplayName(flag.resolvedBy)} on{" "}
                      {flag.resolvedAt?.toLocaleString()}
                    </p>
                  )}
                </div>
              )}
            </>
          )}

          {/* Edit View */}
          {isEditing && (
            <div className="space-y-3">
              <h3 className="text-sm font-medium">Edit Feedback</h3>
              <Textarea
                placeholder="How can the agent improve..."
                value={newFlagText}
                onChange={(e) => setNewFlagText(e.target.value)}
                className="min-h-[80px]"
              />
              <div className="space-y-2">
                <h4 className="text-xs font-medium">Category</h4>
                {flagCategorySelect}
              </div>
              <div className="flex justify-end gap-2 pt-2">
                <Button variant="outline" size="sm" onClick={resetForm}>
                  Cancel
                </Button>
                <Button
                  size="sm"
                  onClick={handleAddOrUpdateFlag}
                  disabled={
                    newFlagText.trim() === "" ||
                    !selectedCategory ||
                    isUpdatingEngagementFlag
                  }
                >
                  Update Feedback
                </Button>
              </div>
            </div>
          )}

          {/* Resolve Confirmation View */}
          {isResolving && (
            <div className="space-y-3">
              <h3 className="text-sm font-medium">Resolve Feedback</h3>
              <div className="mb-3 flex items-center gap-2">
                <Badge variant="outline" className="flex items-center gap-1">
                  <FlagIcon className="h-3 w-3" />
                  {
                    engagementFlagCategories[
                      flag.category as keyof typeof engagementFlagCategories
                    ].label
                  }
                </Badge>
                <p className="text-muted-foreground text-sm">{flag.notes}</p>
              </div>
              <div className="space-y-2">
                <h4 className="text-xs font-medium">Resolution Category</h4>
                <Select
                  value={resolutionCategory}
                  onValueChange={(value) =>
                    setResolutionCategory(
                      value as EngagementFlagResolutionCategory,
                    )
                  }
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select a category" />
                  </SelectTrigger>
                  <SelectContent>
                    {Object.entries(engagementFlagResolutionCategories).map(
                      ([value, { label, icon: CategoryIcon }]) => (
                        <SelectItem key={value} value={value}>
                          <div className="flex items-center">
                            <CategoryIcon className="mr-1.5 h-3.5 w-3.5" />
                            {label}
                          </div>
                        </SelectItem>
                      ),
                    )}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <h4 className="text-xs font-medium">Reason</h4>
                <Textarea
                  placeholder="Enter any resolution notes..."
                  value={resolutionReason}
                  onChange={(e) => setResolutionReason(e.target.value)}
                  className="min-h-[60px]"
                />
              </div>
              <div className="flex justify-end gap-2 pt-2">
                <Button variant="outline" size="sm" onClick={resetForm}>
                  Cancel
                </Button>
                <Button
                  size="sm"
                  onClick={confirmResolution}
                  disabled={
                    resolutionReason.trim() === "" ||
                    !resolutionCategory ||
                    isResolvingEngagementFlag
                  }
                >
                  Confirm Resolution
                </Button>
              </div>
            </div>
          )}
        </div>
      );
    });

  return (
    <SidePanel
      title="Train your AI Agent"
      subtitle="By sharing feedback your AI will learn from your preferences and improve over time"
      trigger={children}
      size="md"
    >
      {!showAddForm && !editingFlagId && !resolvingFlagId && (
        <Button className="w-full" onClick={handleOpenNewFlagForm}>
          <IconAdd className="mr-2 h-4 w-4" />
          Add New Feedback
        </Button>
      )}

      {showAddForm && (
        <div className="space-y-3 rounded-md border p-3">
          <h3 className="text-sm font-medium">Add New Feedback</h3>
          <div className="space-y-2">
            <h4 className="text-xs font-medium">Category</h4>
            {flagCategorySelect}
          </div>
          <Textarea
            placeholder="How can the agent improve..."
            value={newFlagText}
            onChange={(e) => setNewFlagText(e.target.value)}
            className="min-h-[80px]"
          />

          <div className="flex justify-end gap-2 pt-2">
            <Button variant="outline" size="sm" onClick={resetForm}>
              Cancel
            </Button>
            <Button
              size="sm"
              onClick={handleAddOrUpdateFlag}
              disabled={
                newFlagText.trim() === "" ||
                !selectedCategory ||
                isCreatingEngagementFlag
              }
            >
              Create Feedback
            </Button>
          </div>
        </div>
      )}

      <div className="mt-4 space-y-3">
        {engagementFlags.length === 0 && !showAddForm ? (
          <p className="text-muted-foreground py-4 text-center text-sm">
            No feedback created yet
          </p>
        ) : (
          <>
            {flags.length > 0 && (
              <>
                <h3 className="text-sm font-medium">Active Feedback</h3>{" "}
                {renderFlags(flags)}
              </>
            )}
            {resolvedFlags.length > 0 && (
              <>
                <h3 className="text-sm font-medium">Resolved Feedback</h3>{" "}
                {renderFlags(resolvedFlags)}
              </>
            )}
          </>
        )}
      </div>
    </SidePanel>
  );
