import { NextResponse } from "next/server";

import { z } from "zod";

import { checkApiRequestAuth } from "@/common/libs/check-api-request-auth";
import { env } from "@/env";

import { rescheduleAgentAction } from "./reschedule-agent-action";
import { triggerFollowupAgentAction } from "./trigger-followup-agent-action";

const actionMapper: Record<
  string,
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  (input: any) => Promise<object>
> = {
  reschedule: rescheduleAgentAction,
  triggerFollowup: triggerFollowupAgentAction,
};

export async function POST(request: Request) {
  try {
    checkApiRequestAuth(request, env.AGENT_AUTH_TOKEN_SECRET);

    const body = (await request.json()) as unknown;

    const parsedBody = z
      .object({
        actionName: z.string(),
        input: z.unknown(),
      })
      .parse(body);

    const action = actionMapper[parsedBody.actionName];

    if (!action) {
      throw new Error(`Invalid action: ${parsedBody.actionName}`);
    }

    const result = await action(parsedBody.input);

    return NextResponse.json(result);
  } catch (error) {
    console.error("Error creating engagement:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

