"use client";

import { Label } from "@purplefish-ai/shadcn-ui/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@purplefish-ai/shadcn-ui/components/ui/select";

import type { CallFlowTask } from "@/common/models/interview-builder";
import { LanguageSelector } from "@/components/interview-builder/language-selector";

import {
  DataPointCombobox,
  type DataPointSchema,
} from "../../data-point-combobox";
import { AIConfigurationSection } from "./shared/ai-configuration-section";
import { SimpleTaskHeader } from "./shared/simple-task-header";
import {
  type ValidationProperty,
  ValidationSection,
} from "./shared/validation-section";
import type { TaskEditModeProps } from "./types";

export function DataCollectionTaskCard({
  task,
  availableDataPoints,
  schemas,
  fallbackLanguage = "en",
  onUpdate,
  onDelete,
  onToggleActive,
}: TaskEditModeProps) {
  const handleFieldChange = (
    field: keyof CallFlowTask,
    value: string | boolean | undefined | unknown[],
  ) => {
    const updated = {
      ...task,
      [field]: value,
    };
    onUpdate(updated);
  };

  const handleDataPointSelect = (dataPoint: string) => {
    const schema = schemas?.find((s) => s.schemaKey === dataPoint);
    const defaultPrompt = schema?.defaultPrompt ?? "";

    const shouldUpdateMessage =
      !task.initialMessage || task.initialMessage === "";

    const updated = {
      ...task,
      candidateDataPointToCollect: dataPoint,
      ...(shouldUpdateMessage && defaultPrompt
        ? { initialMessage: defaultPrompt }
        : {}),
    };
    onUpdate(updated);
  };

  const selectedDataPoint = schemas?.find(
    (s) => s.schemaKey === task.candidateDataPointToCollect,
  );
  const dataPointLabel =
    selectedDataPoint?.jsonSchema?.title ||
    task.candidateDataPointToCollect ||
    "Data Collection";

  return (
    <>
      <SimpleTaskHeader
        task={task}
        label={`Collect: ${dataPointLabel}`}
        onDelete={onDelete}
        onClose={onToggleActive}
      />

      {/* Data Point Selection */}
      <div className="mb-4">
        <Label className="mb-1 block text-sm font-medium">Data Point</Label>
        {schemas ? (
          <DataPointCombobox
            value={task.candidateDataPointToCollect || ""}
            onValueChange={handleDataPointSelect}
            dataPoints={schemas.map(
              (s): DataPointSchema => ({
                schemaKey: s.schemaKey,
                schemaVersion: null,
                jsonSchema: {
                  title: s.jsonSchema?.title,
                  type: s.jsonSchema?.type,
                  // eslint-disable-next-line @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-member-access
                  description: (s.jsonSchema as any)?.description as
                    | string
                    | undefined,
                  properties: s.jsonSchema?.properties as
                    | Record<
                        string,
                        {
                          title?: string;
                          type?: string;
                          description?: string;
                          format?: string;
                        }
                      >
                    | undefined,
                  required: s.jsonSchema?.required,
                },
              }),
            )}
          />
        ) : (
          <Select
            value={task.candidateDataPointToCollect || ""}
            onValueChange={handleDataPointSelect}
          >
            <SelectTrigger>
              <SelectValue placeholder="Select a data point..." />
            </SelectTrigger>
            <SelectContent>
              {availableDataPoints.map((dataPoint) => (
                <SelectItem key={dataPoint.key} value={dataPoint.key}>
                  {dataPoint.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}
      </div>

      <div className="space-y-4">
        {/* AI Configuration */}
        <AIConfigurationSection
          task={task}
          onInitialMessageChange={(message) =>
            handleFieldChange("initialMessage", message)
          }
          onInstructionsChange={(instructions) =>
            handleFieldChange("instructions", instructions)
          }
        />

        {/* Validations Section */}
        {task.candidateDataPointToCollect && schemas && (
          <ValidationSection
            task={task}
            properties={(() => {
              const schema = schemas.find(
                (s) => s.schemaKey === task.candidateDataPointToCollect,
              );
              const properties = schema?.jsonSchema?.properties || {};
              const required = schema?.jsonSchema?.required || [];

              return Object.entries(properties).map(
                ([key, prop]): ValidationProperty => {
                  const propDef = prop as {
                    type?: string;
                    title?: string;
                    format?: string;
                  };
                  const propType = propDef.type || "string";
                  const isDateField =
                    propType === "string" &&
                    (propDef.format === "date-time" ||
                      propDef.format === "date");

                  return {
                    key,
                    label: propDef.title || key,
                    type: isDateField
                      ? "date"
                      : (propType as "string" | "number" | "boolean" | "date"),
                    required: required.includes(key),
                    defaultValue: isDateField ? new Date().toISOString() : "",
                    defaultOperator: "eq",
                  };
                },
              );
            })()}
            onValidationsChange={(validations) =>
              handleFieldChange("validations", validations)
            }
          />
        )}

        {/* Language Selection */}
        <LanguageSelector
          language={task.language}
          fallbackLanguage={fallbackLanguage}
          onLanguageChange={(value) => handleFieldChange("language", value)}
        />
      </div>
    </>
  );
}

